package com.logplatform.alert.repository;
import com.logplatform.alert.domain.IncidentEntity; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*;
public interface IncidentRepository extends JpaRepository<IncidentEntity,Long>{ Optional<IncidentEntity> findFirstByTenantIdAndFingerprintAndStatusIn(String tenant,String fp,Collection<String> statuses); Optional<IncidentEntity> findByIdAndTenantId(Long id,String tenant); List<IncidentEntity> findByTenantIdOrderByLastSeenAtDesc(String tenant); List<IncidentEntity> findByTenantIdAndStatusOrderByLastSeenAtDesc(String tenant,String status); }
